        {"kind": "trace", "sql": "SELECT MIN(time) AS first_server_span, MAX(time) AS last_server_span, COUNT(*) AS n FROM abnormal_traces WHERE service_name = 'ts-order-other-service' AND attr_span_kind = 'Server'", "claim": "order-other emits no server spans until about 12:51:25, after a gap starting near 12:50:32, then recovers."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) AS n, MIN(time) AS t0, MAX(time) AS t1 FROM abnormal_traces WHERE service_name = 'ts-seat-service' AND attr_span_kind = 'Client' AND attr_status_code = 'Error' GROUP BY ALL", "claim": "seat's outbound calls fail with no HTTP status from 12:50:33 to 12:51:23, the same window as order-other's gap."},
        {"kind": "log", "sql": "SELECT time, level, message FROM abnormal_logs WHERE service_name = 'ts-seat-service' AND level = 'SEVERE' ORDER BY time LIMIT 5", "claim": "seat logs SEVERE I/O errors on POST requests to ts-order-other-service during the same window."}
